
function renderProductAdmin(){
 const holder=document.querySelector('#product-admin');
 if(holder.contains(document.activeElement))return;
 holder.innerHTML=products().map(p=>`<div class="product-admin ${p.active?'':'blocked'}"><div><b>${escape(p.code)} · ${escape(p.dish)}</b><small>${escape(p.fr)} · ${money(p.price)}</small></div><form class="price-editor" data-price-code="${p.code}"><label for="price-${p.code}">售价 €</label><input id="price-${p.code}" type="number" min="0" max="99999.99" step="0.01" required value="${Number(p.price).toFixed(2)}"><button class="button primary" type="submit">保存价格</button></form><button class="button" data-toggle="${p.code}">${p.active?'下架':'上架'}</button></div>`).join('');
 holder.querySelectorAll('form').forEach(form=>form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('button'),input=form.querySelector('input'),code=form.dataset.priceCode,old=BaoCatalog.get(code).price;button.disabled=true;try{await BaoCatalog.update(code,{price:Number(input.value)});audit('修改价格',code+' · '+money(old)+' → '+money(Number(input.value)));document.activeElement?.blur();initAdminDelete();document.querySelector('#price-message').textContent=code+' 价格已保存，POS 和自助点餐自动更新';}catch(error){document.querySelector('#price-message').textContent=error.message}finally{button.disabled=false}});
 holder.querySelectorAll('[data-toggle]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{const code=button.dataset.toggle,active=!BaoCatalog.get(code).active;await BaoCatalog.update(code,{active});audit(active?'商品上架':'商品下架',code);button.blur();initAdminDelete()}catch(error){document.querySelector('#price-message').textContent=error.message}finally{button.disabled=false}});
}
window.addEventListener('bao-catalog-change',()=>{if(document.body.dataset.page==='admin')renderProductAdmin()});
const ORDER_KEY='baoDumplingOrders',CATALOG_KEY='baoDumplingCatalog',AUDIT_KEY='baoDumplingAudit',ADJUSTMENT_KEY='baoDumplingAdjustments',ARCHIVE_KEY='baoDumplingMonthArchives',PASSWORD_KEY='baoDumplingManagerPassword';

const read=(key,fallback=[])=>JSON.parse(localStorage.getItem(key)||JSON.stringify(fallback));
const write=(key,value)=>localStorage.setItem(key,JSON.stringify(value));
const products=()=>BaoCatalog.all();
const orders=()=>read(ORDER_KEY);
const adjustments=()=>read(ADJUSTMENT_KEY);
const month=()=>new Date().toISOString().slice(0,7),day=()=>new Date().toDateString();
const money=value=>`${Number(value||0).toFixed(2).replace('.',',')} €`;
const escape=value=>String(value??'').replace(/[&<>"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[char]));
const quantity=item=>Math.max(1,Number(item.qty)||1);
const orderTotal=order=>(order.items||[]).reduce((sum,item)=>sum+Number(item.price||0)*quantity(item),0);
const paid=order=>order.status==='paid'||order.status==='done';
const financialTotal=order=>Number(order.paidTotal??orderTotal(order))+Number((order.corrections||[]).reduce((sum,item)=>sum+Number(item.amount||0),0));
const audit=(action,details)=>{const list=read(AUDIT_KEY);list.push({time:new Date().toLocaleString('fr-FR'),action,details});write(AUDIT_KEY,list.slice(-250));};
function requireManager(){return true}
function productByCode(code){return products().find(item=>item.code.toUpperCase()===String(code).trim().toUpperCase())}
function itemFromProduct(product,qty=1){return {code:product.code,category:product.category,dish:product.dish,fr:product.fr,price:Number(product.price),qty:Number(qty)}}
function saveOrders(value){write(ORDER_KEY,value)}
function activePaid(){return orders().filter(order=>paid(order)&&order.status!=='cancelled')}
function netFor(filter){const sales=activePaid().filter(filter).reduce((sum,order)=>sum+financialTotal(order),0);const manual=adjustments().filter(item=>item.kind!=='correction'&&filter(item)).reduce((sum,item)=>sum+Number(item.amount||0),0);return sales+manual}
function navRefresh(){window.addEventListener('storage',event=>{if(event.key===CATALOG_KEY||page==='pos')return;if(page==='admin')initAdminDelete();if(page==='owner')initOwner()});}
function initPOS(){let cart=[],payment='现金';const catalog=document.querySelector('#pos-catalog'),cartBox=document.querySelector('#pos-cart'),input=document.querySelector('#code-input');function render(){const list=products().filter(item=>item.active);catalog.innerHTML=list.map(item=>`<button class="product" data-code="${item.code}"><b>${item.code}</b><strong>${item.dish}</strong><small>${item.fr} · ${money(item.price)}</small></button>`).join('');catalog.querySelectorAll('button').forEach(button=>button.onclick=()=>add(button.dataset.code));document.querySelector('#cart-count').textContent=`${cart.reduce((n,item)=>n+quantity(item),0)} 件`;cartBox.innerHTML=cart.length?cart.map((item,index)=>`<div class="cart-row"><span><b>${item.code}</b> ${item.dish}<small> ${item.fr} × ${quantity(item)}</small></span><span>${money(item.price*quantity(item))}<button class="button" data-remove="${index}" style="padding:3px 6px;margin-left:5px">×</button></span></div>`).join(''):'<p class="empty">请输入编码或点击商品。</p>';cartBox.querySelectorAll('[data-remove]').forEach(button=>button.onclick=()=>{cart.splice(Number(button.dataset.remove),1);render()});document.querySelector('#pos-total').textContent=money(cart.reduce((sum,item)=>sum+item.price*quantity(item),0))}function add(code){const product=productByCode(code);if(!product||!product.active){alert('未找到可售商品编码 / Code indisponible');return}const existing=cart.find(item=>item.code===product.code);if(existing)existing.qty=quantity(existing)+1;else cart.push(itemFromProduct(product));input.value='';render()}document.querySelector('#add-code').onclick=()=>add(input.value);input.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();add(input.value)}});document.querySelectorAll('.pay').forEach(button=>button.onclick=()=>{payment=button.dataset.payment;document.querySelectorAll('.pay').forEach(item=>item.classList.toggle('selected',item===button))});document.querySelector('#clear-pos').onclick=()=>{cart=[];render()};document.querySelector('#pay-pos').onclick=async()=>{const payButton=document.querySelector('#pay-pos');if(payButton.disabled)return;payButton.disabled=true;try{if(!await BaoCatalog.refresh()){alert('无法核对云端价格，请联网后重试');return}cart=BaoCatalog.reprice(cart);render();if(!cart.length){alert('请先添加商品 / Ajoutez un produit');return}const now=new Date(),order={id:`BD-${now.toISOString().slice(0,10).replaceAll('-','')}-${String(now.getTime()).slice(-5)}`,day:day(),month:month(),time:now.toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'}),items:cart.map(item=>({...item})),total:cart.reduce((sum,item)=>sum+item.price*quantity(item),0),paidTotal:cart.reduce((sum,item)=>sum+item.price*quantity(item),0),status:'paid',payment,source:'pos',kitchenStatus:'new',corrections:[]};window.dispatchEvent(new CustomEvent("bao-pos-order",{detail:order}));const list=orders();list.push(order);saveOrders(list);audit('POS 收款',`${order.id} · ${money(order.paidTotal)} · ${payment}`);cart=[];render();alert(`已收款并发送至厨房\n${order.id}`)}finally{payButton.disabled=false}};window.addEventListener('bao-catalog-change',render);render();input.focus()}
function kitchenLabel(status){return status==='making'?'制作中':status==='ready'?'待取餐':status==='complete'?'已完成':'待制作'}
function initKitchen(){const board=document.querySelector('#kitchen-board'),columns=[['new','待制作 · À préparer','making','开始制作'],['making','制作中 · En cours','ready','待取餐'],['ready','待取餐 · Prêt','complete','完成出餐']];function render(){const list=orders().filter(order=>paid(order)&&order.status!=='cancelled'&&(order.kitchenStatus||'new')!=='complete');board.innerHTML=columns.map(([status,title,next,label])=>`<section class="kitchen-column"><p class="eyebrow">${title}</p>${list.filter(order=>(order.kitchenStatus||'new')===status).map(order=>`<article class="ticket"><h3>${order.id}</h3><small>${order.time} · ${order.source==='pos'?'POS':'自助'}</small><p>${order.items.map(item=>`${escape(item.code||'')} · ${escape(item.dish)} × ${quantity(item)}`).join('<br>')}</p><button class="button ${status==='ready'?'green':''}" data-id="${order.id}" data-next="${next}">${label}</button></article>`).join('')||'<p class="empty">暂无订单</p>'}</section>`).join('');board.querySelectorAll('button').forEach(button=>button.onclick=()=>{const list=orders(),order=list.find(item=>item.id===button.dataset.id);order.kitchenStatus=button.dataset.next;saveOrders(list);audit('厨房状态',`${order.id} · ${kitchenLabel(order.kitchenStatus)}`);render()})}render();setInterval(render,2500)}
function refundOrder(id){const list=orders(),order=list.find(item=>item.id===id);if(!order||!requireManager())return;const amount=financialTotal(order);if(!confirm(`确认退款并取消 ${id}？\n退款金额：${money(amount)}`))return;order.status='cancelled';order.refundAmount=amount;order.refundedAt=new Date().toISOString();saveOrders(list);audit('退款取消',`${id} · ${money(amount)}`);initAdmin()}
function correctOrder(id){openDeleteDialog(id)}
function initAdmin(){const list=orders(),todayOrders=list.filter(order=>order.day===day()),net=netFor(order=>order.day===day()),refunds=todayOrders.filter(order=>order.status==='cancelled'&&order.refundAmount).reduce((sum,order)=>sum+Number(order.refundAmount),0);document.querySelector('#admin-net').textContent=money(net);document.querySelector('#admin-paid').textContent=todayOrders.filter(paid).length;document.querySelector('#admin-refunds').textContent=money(refunds);document.querySelector('#admin-kitchen').textContent=todayOrders.filter(order=>paid(order)&&!['ready','complete'].includes(order.kitchenStatus||'new')).length;const holder=document.querySelector('#admin-orders');holder.innerHTML=todayOrders.length?[...todayOrders].reverse().map(order=>`<article class="order-row"><div class="order-top"><b>${order.id}</b><span class="status ${order.status}">${order.status==='cancelled'?'已退款取消':order.status==='paid'?'已付款':'已完成'}</span></div><p>${order.items.map(item=>`${escape(item.code||'')} · ${escape(item.dish)} × ${quantity(item)}`).join('<br>')}</p><footer><strong>${money(financialTotal(order))}</strong>${order.status!=='cancelled'?`<span><button class="button" data-correct="${order.id}">纠错</button><button class="button danger" data-refund="${order.id}">退款取消</button></span>`:''}</footer></article>`).join(''):'<p class="empty">今日暂无订单</p>';holder.querySelectorAll('[data-correct]').forEach(button=>button.onclick=()=>correctOrder(button.dataset.correct));holder.querySelectorAll('[data-refund]').forEach(button=>button.onclick=()=>refundOrder(button.dataset.refund));renderProductAdmin();document.querySelector('#admin-audit').innerHTML=read(AUDIT_KEY).slice(-12).reverse().map(entry=>`<div><b>${escape(entry.action)}</b> · ${escape(entry.details)}<br><small>${escape(entry.time)}</small></div>`).join('')||'<p class="empty">暂无操作记录</p>';document.querySelector('#admin-close-month').onclick=closeMonth}
function closeMonth(){if(!requireManager())return;const key=month();if(!confirm(`确认结账并归档 ${key}？\n历史订单保留，但不再允许修改。`))return;const archived=read(ARCHIVE_KEY);if(archived.some(item=>item.month===key)){alert('该月份已经结账 / Mois déjà clôturé');return}const monthOrders=orders().filter(order=>order.month===key),refunds=monthOrders.filter(order=>order.refundAmount).reduce((sum,order)=>sum+Number(order.refundAmount),0),net=netFor(order=>order.month===key);archived.push({month:key,net,refunds,orders:monthOrders.length,closedAt:new Date().toLocaleString('fr-FR')});write(ARCHIVE_KEY,archived);audit('月度结账',`${key} · ${money(net)}`);alert('月度已归档 / Mois archivé');initAdmin()}
function initOwner(){const monthOrders=orders().filter(order=>order.month===month()),refunds=monthOrders.filter(order=>order.refundAmount).reduce((sum,order)=>sum+Number(order.refundAmount),0);document.querySelector('#owner-today').textContent=money(netFor(order=>order.day===day()));document.querySelector('#owner-month').textContent=money(netFor(order=>order.month===month()));document.querySelector('#owner-refunds').textContent=money(refunds);document.querySelector('#owner-orders').textContent=monthOrders.filter(order=>order.status!=='cancelled').length;const totals={};monthOrders.filter(order=>order.status!=='cancelled').forEach(order=>order.items.forEach(item=>{totals[item.dish]=(totals[item.dish]||0)+quantity(item)}));const ranked=Object.entries(totals).sort((a,b)=>b[1]-a[1]),max=ranked[0]?.[1]||1;document.querySelector('#owner-products').innerHTML=ranked.length?ranked.slice(0,6).map(([name,count])=>`<div class="bar-line"><span>${escape(name)}</span><i style="width:${Math.max(8,count/max*100)}%"></i><b>${count} 份</b></div>`).join(''):'<p class="empty">本月尚无销售</p>';document.querySelector('#owner-archives').innerHTML=read(ARCHIVE_KEY).slice().reverse().map(item=>`<div><b>${item.month}</b> · ${money(item.net)}<br><small>${item.orders} 单 · ${escape(item.closedAt)}</small></div>`).join('')||'<p class="empty">尚无归档月份</p>'}
function initPOSAdvanced(){let cart=[],payment='现金',selection={};const catalog=document.querySelector('#pos-catalog'),cartBox=document.querySelector('#pos-cart'),input=document.querySelector('#code-input'),dialog=document.querySelector('#pos-choice'),step=document.querySelector('#pos-step'),title=document.querySelector('#pos-product'),subtitle=document.querySelector('#pos-subtitle'),optionBox=document.querySelector('#pos-options');const fillings=[['韭菜鸡蛋','Poireau et œuf'],['鲜肉','Porc'],['牛肉','Bœuf']],cookings={包子:[['清蒸','Vapeur'],['煎包','Poêlé']],饺子:[['水煮','À l’eau'],['清蒸','Vapeur'],['煎饺','Poêlés']]};function render(){cart=BaoCatalog.reprice(cart);catalog.innerHTML=products().filter(item=>item.active).map(item=>`<button class="product" data-code="${item.code}"><b>${item.code}</b><strong>${item.dish}</strong><small>${item.fr} · ${money(item.price)}</small></button>`).join('');catalog.querySelectorAll('button').forEach(button=>button.onclick=()=>begin(button.dataset.code));document.querySelector('#cart-count').textContent=`${cart.reduce((sum,item)=>sum+quantity(item),0)} 件`;cartBox.innerHTML=cart.length?cart.map((item,index)=>`<div class="cart-row"><span><b>${item.code}</b> ${item.dish}<small>${item.fr}${item.filling?` · ${item.filling} / ${item.fillingFr} · ${item.style} / ${item.styleFr}`:''} × ${quantity(item)}</small></span><span>${money(item.price*quantity(item))}<button class="button" data-remove="${index}" style="padding:3px 6px;margin-left:5px">×</button></span></div>`).join(''):'<p class="empty">请输入编码或点击商品。</p>';cartBox.querySelectorAll('[data-remove]').forEach(button=>button.onclick=()=>{cart.splice(Number(button.dataset.remove),1);render()});document.querySelector('#pos-total').textContent=money(cart.reduce((sum,item)=>sum+item.price*quantity(item),0))}function addItem(){selection.product=BaoCatalog.get(selection.product.code);if(!selection.product?.active){dialog.close();alert('商品已下架');return}const item={...itemFromProduct(selection.product),filling:selection.filling||'',fillingFr:selection.fillingFr||'',style:selection.style||'',styleFr:selection.styleFr||''},same=cart.find(entry=>entry.code===item.code&&entry.filling===item.filling&&entry.style===item.style);if(same)same.qty=quantity(same)+1;else cart.push(item);dialog.close();input.value='';render()}function choices(values,handler){optionBox.innerHTML='';values.forEach(([zh,fr])=>{const button=document.createElement('button');button.type='button';button.innerHTML=`${zh}<small style="display:block;font-weight:400">${fr}</small>`;button.onclick=()=>handler(zh,fr);optionBox.append(button)})}function chooseCooking(){step.textContent='步骤 2 / 2 · Choisir la cuisson';title.textContent=`${selection.product.code} · ${selection.product.dish}`;subtitle.textContent=`${selection.filling} · ${selection.fillingFr}`;choices(cookings[selection.product.category],(zh,fr)=>{selection.style=zh;selection.styleFr=fr;addItem()})}function begin(code){const product=productByCode(code);if(!product||!product.active){alert('未找到可售商品编码 / Code indisponible');return}selection={product};if(product.category==='粥品'){addItem();return}step.textContent='步骤 1 / 2 · Choisir la garniture';title.textContent=`${product.code} · ${product.dish}`;subtitle.textContent=product.fr;choices(fillings,(zh,fr)=>{selection.filling=zh;selection.fillingFr=fr;chooseCooking()});dialog.showModal()}document.querySelector('#add-code').onclick=()=>begin(input.value);input.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();begin(input.value)}});document.querySelectorAll('.pay').forEach(button=>button.onclick=()=>{payment=button.dataset.payment;document.querySelectorAll('.pay').forEach(item=>item.classList.toggle('selected',item===button))});document.querySelector('#clear-pos').onclick=()=>{cart=[];render()};document.querySelector('#pay-pos').onclick=async()=>{const payButton=document.querySelector('#pay-pos');if(payButton.disabled)return;payButton.disabled=true;try{if(!await BaoCatalog.refresh()){alert('无法核对云端价格，请联网后重试');return}cart=BaoCatalog.reprice(cart);render();if(!cart.length){alert('请先添加商品 / Ajoutez un produit');return}const now=new Date(),total=cart.reduce((sum,item)=>sum+item.price*quantity(item),0),order={id:`BD-${now.toISOString().slice(0,10).replaceAll('-','')}-${String(now.getTime()).slice(-5)}`,day:day(),month:month(),time:now.toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'}),items:cart.map(item=>({...item})),total,paidTotal:total,status:'paid',payment,source:'pos',kitchenStatus:'new',corrections:[]};window.dispatchEvent(new CustomEvent("bao-pos-order",{detail:order}));const list=orders();list.push(order);saveOrders(list);audit('POS 收款',`${order.id} · ${money(total)} · ${payment}`);cart=[];render();alert(`已收款并发送至厨房\n${order.id}`)}finally{payButton.disabled=false}};window.addEventListener('bao-catalog-change',render);render();input.focus()}
function kitchenItemText(item){return `${escape(item.code||'')} · ${escape(item.dish)}${item.filling?` · 馅料：${escape(item.filling)} · 做法：${escape(item.style)}`:''} × ${quantity(item)}`}
function initKitchenDetailed(){const board=document.querySelector('#kitchen-board'),columns=[['new','待制作 · À préparer','making','开始制作'],['making','制作中 · En cours','ready','待取餐'],['ready','待取餐 · Prêt','complete','完成出餐']];function render(){const list=orders().filter(order=>(paid(order)||order.source==='self')&&order.status!=='cancelled'&&(order.kitchenStatus||'new')!=='complete');board.innerHTML=columns.map(([status,title,next,label])=>`<section class="kitchen-column"><p class="eyebrow">${title}</p>${list.filter(order=>(order.kitchenStatus||'new')===status).map(order=>`<article class="ticket"><h3>${order.id}</h3><small>${order.time} · ${order.source==='pos'?'POS':'自助'}</small><p>${order.items.map(kitchenItemText).join('<br>')}</p><button class="button ${status==='ready'?'green':''}" data-id="${order.id}" data-next="${next}">${label}</button></article>`).join('')||'<p class="empty">暂无订单</p>'}</section>`).join('');board.querySelectorAll('button').forEach(button=>button.onclick=()=>{const list=orders(),order=list.find(item=>item.id===button.dataset.id);order.kitchenStatus=button.dataset.next;saveOrders(list);audit('厨房状态',`${order.id} · ${kitchenLabel(order.kitchenStatus)}`);render()})}render();setInterval(render,2500)}
function deleteOrderNow(id){const list=orders(),order=list.find(item=>item.id===id);if(!order)return;saveOrders(list.filter(item=>item.id!==id));audit('管理员删除订单',`${id} · ${money(financialTotal(order))}`);initAdminDelete()}
function openDeleteDialog(id){if(confirm('确认删除订单 '+id+'？删除后无法恢复。'))deleteOrderNow(id)}
function initAdminDelete(){initAdmin();document.querySelector('.hint').textContent='管理员可删除错误订单；删除后会实时从厨房、订单数及营业额统计中移除，并保留操作日志。';document.querySelectorAll('[data-correct]').forEach(button=>button.textContent='删除订单')}
const page=document.body.dataset.page;if(page==='pos')initPOSAdvanced();if(page==='kitchen')initKitchenDetailed();if(page==='admin')initAdminDelete();if(page==='owner')initOwner();navRefresh();
